CREATE POLICY sales_images_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'sales-product-images' AND public.can_manage_sales());
CREATE POLICY sales_images_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'sales-product-images' AND public.can_manage_sales() AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY sales_images_update ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'sales-product-images' AND public.can_manage_sales() AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'sales-product-images' AND public.can_manage_sales() AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY sales_images_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'sales-product-images' AND public.can_manage_sales() AND (storage.foldername(name))[1] = auth.uid()::text);